      const byIcon = [[/spotlight/, 'down'], [/light-recessed|downlight/, 'downflat'], [/led-strip/, 'strip'], [/floor-lamp/, 'floorlamp'], [/ceiling-fan-light|fan/, 'fanlight'], [/wall-sconce/, 'sconce'],
        [/flood/, 'flood'], [/desk-lamp/, 'desklamp'], [/lamp/, 'bedside'], [/ceiling-light|chandelier/, 'ceiling'], [/pendant/, 'lamp']];
      for (const [re, k] of byIcon) if (re.test(icon)) return k;
      const byName = [[/track|spotlight/, 'down'], [/downlight|recessed|spot/, 'downflat'], [/strip|led|tape/, 'strip'], [/floor/, 'floorlamp'], [/fan/, 'fanlight'], [/sconce|wall/, 'sconce'],
        [/flood|security/, 'flood'], [/desk|reading/, 'desklamp'], [/drum/, 'drumlamp'], [/dome/, 'pendant2'], [/lamp|bedside/, 'bedside'], [/pendant/, 'lamp'], [/ceiling|oyster/, 'ceiling']];
      for (const [re, k] of byName) if (re.test(name)) return k;
