  const t = ((A.friendly_name || '') + ' ' + id + ' ' + ICON_OF(hass, id)).toLowerCase();
  if (dom === 'person' || dom === 'device_tracker') return 'person';
  if (dc === 'moisture' || /leak|water|flood|moisture/.test(t)) return 'leak';
  if (['smoke', 'gas', 'carbon_monoxide', 'safety'].indexOf(dc) >= 0 || /smoke|gas|carbon/.test(t)) return 'smoke';
  if (['motion', 'occupancy', 'presence', 'moving', 'vibration'].indexOf(dc) >= 0 || /motion|occupan|presence|pir/.test(t)) return 'motion';
  if (dc === 'window' || /window/.test(t)) return /awning|bottom|hopper|louvre|louver/.test(t) ? 'window2' : 'window';
