// a timer's state: time left (counting down while running), how far through, and words for it
function timerModel(s, pend) {
  const A = s.attributes || {}, st = s.state, dur = secsOf(A.duration), now = Date.now();
  const on = st === 'active' || st === 'paused', running = st === 'active', fin = A.finishes_at ? Date.parse(A.finishes_at) : NaN;
  const rem = running && !isNaN(fin) ? Math.max(0, (fin - now) / 1000) : on ? secsOf(A.remaining) : (pend != null ? pend : dur);
  const r = { on, running, st, dur: on ? dur : (pend != null ? pend : dur), rem, val: clockTxt(rem), unit: '', frac: on && dur ? clamp(rem / dur, 0, 1) : 0 };
  r.word = running ? 'Running' : st === 'paused' ? 'Paused' : 'Idle';
  r.endTxt = running && !isNaN(fin) ? tShort(new Date(fin)) : '';
  r.startTxt = running && !isNaN(fin) ? tShort(new Date(fin - dur * 1000)) : '';
  r.finish = running ? 'Finishes ' + r.endTxt : st === 'paused' ? 'Paused · ' + r.val + ' left' : 'Ready · ' + durWords(r.dur);
  return r;
}

