// Home Assistant's map element (ha-map) is loaded with the map card; ask for it once, then wait for it to be defined
let dwMapP = null;
function dwMapReady() {
  if (customElements.get('ha-map')) return Promise.resolve(true);
  if (!dwMapP) dwMapP = (async () => {
    try { const h = window.loadCardHelpers && await window.loadCardHelpers(); if (h) { const c = await h.createCardElement({ type: 'map', entities: ['zone.home'] }); if (c && c.constructor && c.constructor.getConfigElement) {} } } catch (e) { /* the map card may not load in every setup */ }
    await Promise.race([customElements.whenDefined('ha-map'), new Promise((res) => setTimeout(res, 6000))]);
    return !!customElements.get('ha-map');
  })();
  return dwMapP;
}

