// an air purifier: said by its name, model or icon, or a PM2.5 / air quality sensor on the same device
const isPurifier = (hass, id) => {
  const s = hass.states[id], d = devInfo(hass, id), txt = ((s && s.attributes.friendly_name) + ' ' + id + ' ' + (d.name || '') + ' ' + (d.model || '') + ' ' + (d.manufacturer || '') + ' ' + ((s && s.attributes.icon) || '')).toLowerCase();
  if (/purif|air ?clean|air ?filter|pure ?(cool|hot|humid)|levoit|blueair|coway|winix|philips air|mi air|air ?purifier|airmega|vital ?100|core ?[234]00/.test(txt)) return true;
  const dev = deviceOf(hass, id);
  return !!dev && entitiesOfDevice(hass, dev).some((e) => e.startsWith('sensor.') && ['pm25', 'aqi'].indexOf((hass.states[e].attributes || {}).device_class) >= 0);
};
