// the arrangements: the size of each slot, top left to bottom right
const CG_LAYOUTS = { quad: ['1x1', '1x1', '1x1', '1x1'], wide_top: ['2x1', '1x1', '1x1'], wide_bottom: ['1x1', '1x1', '2x1'], two_wide: ['2x1', '2x1'] };
const CG_NAMES = { quad: 'Four small', wide_top: 'Wide on top', wide_bottom: 'Wide below', two_wide: 'Two wide' };
