const cgLayout = (cfg) => { if (CG_LAYOUTS[cfg.layout]) return cfg.layout; const t = (Array.isArray(cfg.tiles) ? cfg.tiles : []).map((x) => (x && x.size === '2x1' ? 'w' : 's')).join(''); return /^w/.test(t) ? (/^ww/.test(t) ? 'two_wide' : 'wide_top') : /^ssw/.test(t) ? 'wide_bottom' : 'quad'; };
// where each slot sits, as a share of the 2 x 2 (the same as the tiles it replaces: 173 + 10 + 173 of 356)
const cgSlots = (lay) => { const U = 173 / 356 * 100, G = 10 / 356 * 100, out = []; let row = 0, col = 0;
  CG_LAYOUTS[lay].forEach((sz) => { if (sz === '2x1') { if (col) { row++; col = 0; } out.push({ size: sz, l: 0, t: row * (U + G), w: 100, h: U }); row++; } else { out.push({ size: sz, l: col * (U + G), t: row * (U + G), w: U, h: U }); col++; if (col > 1) { col = 0; row++; } } });
  return out; };
