  const w = has('weather.')[0]; if (w) add('weather', w, nameOf(hass, w) || 'Weather');
  const ppl = has('person.'); if (ppl.length > 1) add('people', '', 'Everyone', { card_type: 'people', entities: ppl.slice(0, 6), name: 'Family', size: '2x1', style: 'basic' }); else if (ppl.length) add('tracker', ppl[0]);
  // each device, as the editor would make it
  Object.keys(hass.devices || {}).forEach((dv) => { let dt = null; try { dt = deviceType(hass, dv); } catch (e) { dt = null; } if (!dt || !dt.main || !S[dt.main]) return; const d = hass.devices[dv]; add(dt.type, dt.main, d.name_by_user || d.name || nameOf(hass, dt.main)); });
  // entities without a device
