function resolve(hass, cfg) {
  const main = ['solar_forecast', 'energy_price', 'best_time', 'energy_cost', 'power_usage', 'remote'].indexOf(cfg.card_type) >= 0 ? ((cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || (hass.states['sun.sun'] ? 'sun.sun' : Object.keys(hass.states)[0] || '')) : cfg.card_type === 'social' ? ((cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || soFind(hass, cfg.kind === 'accounts' ? 'channel' : cfg.kind) || (hass.states['sun.sun'] ? 'sun.sun' : Object.keys(hass.states)[0] || '')) : cfg.card_type === 'photos' || cfg.card_type === 'room' ? (hass.states['sun.sun'] ? 'sun.sun' : Object.keys(hass.states)[0] || '') : cfg.card_type === 'printer3d' ? ((cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || Object.keys(hass.states).find((e) => /^sensor\..*print_status$/.test(e)) || '') : cfg.card_type === 'station' ? ((cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || stMain(hass)) : cfg.card_type === 'bins' ? (firstOf(hass, cfg.bins) || firstOf(hass, cfg.entities) || (cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || Object.keys(hass.states).find((e) => (hass.entities || {})[e] && hass.entities[e].platform === 'waste_collection_schedule') || '') : cfg.card_type === 'mail' ? ((cfg.mailbox_entity && hass.states[cfg.mailbox_entity] ? cfg.mailbox_entity : '') || (cfg.entity && hass.states[cfg.entity] ? cfg.entity : '') || firstOf(hass, cfg.parcels)) : cfg.card_type === 'tank' || cfg.card_type === 'plants' ? (firstOf(hass, cfg.plants) || firstOf(hass, cfg.entities) || (cfg.entity && hass.states[cfg.entity] ? cfg.entity : '')) : cfg.card_type === 'updates' ? (cfg.entity && hass.states[cfg.entity] ? cfg.entity : Object.keys(hass.states).find((e) => e.startsWith('update.')) || '') : cfg.card_type === 'irrigation' ? irMain(hass, cfg) : cfg.card_type === 'netflow' ? nfMain(hass, cfg) : cfg.card_type === 'clock' ? (cfg.entity || 'clock.local') : cfg.card_type === 'sun' ? (cfg.entity || (hass.states['sun.sun'] ? 'sun.sun' : 'sun.local')) : cfg.card_type === 'moon' ? (cfg.entity || (hass.states['sensor.moon_phase'] ? 'sensor.moon_phase' : 'moon.local')) : cfg.card_type === 'energy' ? 'energy.local' : cfg.card_type === 'alerts' ? 'alerts.local' : cfg.card_type === 'health' ? (cfg.entity || (cfg.device ? mainOfDevice(hass, cfg.device) : '') || 'health.local') : cfg.card_type === 'graph' ? (cfg.entity || (Array.isArray(cfg.entities) && cfg.entities.map((x) => (typeof x === 'string' ? x : x && x.entity)).find((x) => x && hass.states[x])) || '') : (cfg.card_type === 'group' || cfg.card_type === 'timers' || cfg.card_type === 'people' || cfg.card_type === 'covers' || cfg.card_type === 'locks' || cfg.card_type === 'lights' || cfg.card_type === 'actions' || cfg.card_type === 'plugs' || cfg.card_type === 'graphs' || cfg.card_type === 'cars' || cfg.card_type === 'appliances' || cfg.card_type === 'network' || cfg.card_type === 'servers' || cfg.card_type === 'cameras') ? ((Array.isArray(cfg.entities) && cfg.entities.map((x) => (typeof x === 'string' ? x : x && x.entity)).find((x) => x && hass.states[x])) || cfg.entity || '') : cfg.entity || (cfg.device ? mainOfDevice(hass, cfg.device) : '');
  const type = cfg.card_type && TYPES[cfg.card_type] ? cfg.card_type : (typeOfEntity(hass, main) || 'light');
  const T = TYPES[type];
  const autoSub = main && hass.states[main] ? T.detect(hass, main) : T.subtypes[0][0];
  const sub = cfg.sub_type && T.subtypes.find((x) => x[0] === cfg.sub_type) ? cfg.sub_type : autoSub;
  const size = SIZES[cfg.size] ? cfg.size : '1x1';
  const uiStyle = styleFor(size, cfg.style, type);
  // the icon on detailed cards is off unless show_icon is on (old configs with the no-icon style keep it off)
  const style = uiStyle === 'detailed' && cfg.show_icon !== true && noIconOK(type, size) ? 'detailed_no_icon' : uiStyle;
  const grp = type === 'cover' && !!main && !!coverMembers(hass, main);
  const tap = (cfg.tap_action && cfg.tap_action.action) || defaultTap(size, type, uiStyle);
  if (GROUPY({ type, style: uiStyle })) return { main, type, T, sub, autoSub, size, style, uiStyle, grp, tap: 'none' };
  if (type === 'graph' && GR_CMP(sub, cfg)) return { main, type, T, sub, autoSub, size, style, uiStyle, grp, tap: 'none', cmp: true };
  return { main, type, T, sub, autoSub, size, style, uiStyle, grp, tap: tap === 'flip' && !flipOK(type, size, style, grp) ? 'more-info' : tap };
}

