  const dead = S === 'unavailable' || S === 'unknown';
  const states = p.states || {};
  const st = (i) => (i ? states[i] : undefined);
  const num = (i, d) => { const s = st(i); const n = s ? parseFloat(s.state) : NaN; return isNaN(n) ? d : n; };
  const txt = (i) => { const s = st(i); return s && s.state !== 'unavailable' && s.state !== 'unknown' ? s.state : '--'; };
  const clamp = (x, a, b) => Math.min(Math.max(x, a), b);
  const cap = (x) => (x ? String(x).replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase()) : '');
  const LIGHT = { lamp: 1, pendant2: 1, floorlamp: 1, down: 1, downflat: 1, fanlight: 1, sconce: 1, flood: 1, strip: 1, bedside: 1, ceiling: 1 };
