    laptop: () => SV(O('rect', 'x="13" y="16" width="70" height="50" rx="5"') + Dt('rect', 'x="16" y="19" width="64" height="44" rx="2.5"') +
      IN(level(F('rect', 'x="18" y="21" width="60" height="40" rx="1.5"'), 21, 61)) +
      F('rect', 'x="43" y="19" width="10" height="3.5" rx="1.5"', t.softBg) +
      O('path', 'd="M5 66H91V69Q91 73 87 73H9Q5 73 5 69Z"') + Dt('rect', 'x="40" y="66" width="16" height="2.5" rx="1.25"')),
    // power: the bolt sits just inside the inner circle
    power: () => SV(O('circle', 'cx="48" cy="50" r="40"') + Dt('circle', 'cx="48" cy="50" r="29"') +
      IN(F('path', 'd="M53 22L33 54H47L42 80L64 45H50L56 22Z" transform="translate(48.5 51) scale(0.8) translate(-48.5 -51)"'))),
    // humidity: the same drop as the rain rate tile
    humid: () => dropHero(t.col),
    raindrop: () => dropHero('var(--hamptons-color-13, var(--dw-p13))'),
    // light level: the rays grow with the brightness
    lux: () => {
      const L = 4 + 11 * fr;
      const rays = [0, 45, 90, 135, 180, 225, 270, 315].map((a) => {
        const r = a * Math.PI / 180;
        return 'M' + (48 + 27 * Math.cos(r)).toFixed(1) + ' ' + (50 + 27 * Math.sin(r)).toFixed(1) + 'L' + (48 + (27 + L) * Math.cos(r)).toFixed(1) + ' ' + (50 + (27 + L) * Math.sin(r)).toFixed(1);
      }).join(' ');
      return SV(O('circle', 'cx="48" cy="50" r="21"') + (on ? IN(F('circle', 'cx="48" cy="50" r="15"') + FS(rays, 6)) : DS(rays, 6)));
    },
    // charging pad, seen from above: off, the empty pad with its light dim; on, a phone lies on it charging (its screen fills, a bolt, waves at the sides)
    chargepad: () => {
      const f = clamp(geo.fill > 0 ? geo.fill : 0.6, 0.15, 1), top = 18 + 60 * (1 - f);
      return SV(O('circle', 'cx="48" cy="48" r="36"') + Dt('circle', 'cx="48" cy="48" r="29"') +
        (on ? IN(FS('M12 36q-5 12 0 24', 3) + FS('M84 36q5 12 0 24', 3)) +
          O('rect', 'x="30" y="12" width="36" height="72" rx="8"') + el('rect', 'x="34" y="18" width="28" height="60" rx="4"', 'fill:' + g.card) +
          IN(F('rect', 'x="34" y="' + top.toFixed(1) + '" width="28" height="' + (78 - top).toFixed(1) + '" rx="4"')) +
          el('path', 'd="M49.5 38L42.5 49H48L46.5 58L53.5 47H48Z"', 'fill:' + (f > 0.45 ? g.card : t.col))
          : el('circle', 'cx="48" cy="48" r="12"', 'fill:' + t.softBg + ';filter:url(#' + t.fDet + ')') + el('circle', 'cx="48" cy="48" r="4"', 'fill:' + t.ghost)));
    },
