      snow: (x, y) => [0, 60, 120].map((a) => '<g transform="rotate(' + a + ' ' + x + ' ' + y + ')">' + ink('M' + x + ' ' + (y - 12) + 'v24M' + (x - 4) + ' ' + (y - 9) + 'l4 3 4-3M' + (x - 4) + ' ' + (y + 9) + 'l4-3 4 3', 2.6, 0.85) + '</g>').join(''),
      tumble: (x, y) => ink('M' + (x - 11) + ' ' + (y - 3) + 'a11 11 0 0 1 19-6', 3, 0.85) + blob('M' + (x + 10) + ' ' + (y - 13) + 'l1 8-8-1z', 0.85) + ink('M' + (x + 11) + ' ' + (y + 3) + 'a11 11 0 0 1-19 6', 3, 0.85) + blob('M' + (x - 10) + ' ' + (y + 13) + 'l-1-8 8 1z', 0.85),
      spin: (x, y) => ink('M' + x + ' ' + (y - 13) + 'a13 13 0 1 1-12 8', 3, 0.85) + ink('M' + x + ' ' + (y - 6) + 'a6 6 0 1 1-5 4', 2.6, 0.7) + blob('M' + (x - 15) + ' ' + (y - 1) + 'l3-8 5 6z', 0.85),
      mesh: (x, y) => '<rect x="' + (x - 11) + '" y="' + (y - 9) + '" width="22" height="18" rx="3" fill="none" stroke-width="2.6" style="stroke:' + cc + '" stroke-opacity="0.9"></rect>' + ink('M' + (x - 11) + ' ' + (y - 3) + 'h22M' + (x - 11) + ' ' + (y + 3) + 'h22M' + (x - 4) + ' ' + (y - 9) + 'v18M' + (x + 4) + ' ' + (y - 9) + 'v18', 1.6, 0.7),
      sparkle: (x, y) => blob('M' + (x - 5) + ' ' + (y - 14) + 'c1 5 3 7 8 8-5 1-7 3-8 8-1-5-3-7-8-8 5-1 7-3 8-8z', 0.92) + blob('M' + (x + 8) + ' ' + (y + 1) + 'c.6 3 2 4.4 5 5-3 .6-4.4 2-5 5-.6-3-2-4.4-5-5 3-.6 4.4-2 5-5z', 0.85)
