      blob('M' + (x + 5) + ' ' + (y + h * 0.36) + 'v-7a2 2 0 0 1 2-2h5a2 2 0 0 1 2 2v7z', 0.6) + dot(x + w - 9, y + h * 0.36 - 4, 4, 0.6) + blob('M' + (x + 5) + ' ' + (y + h * 0.68) + 'v-9h6v9z', 0.55) + dot(x + w - 8, y + h * 0.68 - 4, 3.5, 0.55);
