        const root = await browse();
        const fav = (root.children || []).find((q) => q.media_content_type === 'favorites' || /^favou?rites$/i.test(q.title || ''));
        if (!fav) throw new Error('No Sonos favourites found');
        const node = await browse(fav.media_content_id, fav.media_content_type), out = [];
        for (const q of node.children || []) {
          if (out.length >= 48) break;
          if (q.can_play && !q.can_expand) out.push(q);
          else if (q.can_expand) { try { const sub = await browse(q.media_content_id, q.media_content_type); (sub.children || []).filter((z) => z.can_play).forEach((z) => out.push(z)); } catch (e) { /* skip that folder */ } }
        }
        return out.slice(0, 48).map((q) => ({ title: q.title, id: q.media_content_id, type: q.media_content_type, thumb: q.thumbnail || '' }));
