    if (lq) m.light = { id: E.light, on: lq.state === 'on', pct: lq.state === 'on' ? (lq.attributes.brightness != null ? Math.round(lq.attributes.brightness / 2.55) : 100) : 0, dim: lightCaps(lq).dimmable };
