    return '<span class="pill" style="height:20px;padding:0 7px;font-size:10.5px;gap:3px;flex:none;background:' + mix(c, 22) + ';color:color-mix(in srgb,' + c + ' 75%,var(--primary-text-color))"><ha-icon icon="' + (dd.kind === 'over' ? 'mdi:alert-circle-outline' : 'mdi:calendar-blank-outline') + '" style="--mdc-icon-size:11px;display:flex"></ha-icon>' + esc(dd.txt) + '</span>';
