  _tdCount(n, c) { return '<span class="pill" style="height:22px;min-width:22px;justify-content:center;padding:0 7px;font-weight:700;background:' + mix(c, 24) + ';color:color-mix(in srgb,' + c + ' 75%,var(--primary-text-color))">' + n + '</span>'; }
