  _tdEmpty(d) { return !d.ready ? 'Reading the list…' : !d.id ? 'Pick a to-do list under Customise' : d.n ? '' : d.nd ? 'All done' : 'Nothing on the list'; }
  _tdSum(d) { return [d.late.length ? d.late.length + ' late' : '', d.nd ? d.nd + ' done' : ''].filter(Boolean).join(' · ') || (d.n ? 'Nothing late' : this._tdEmpty(d)); }
