        box.innerHTML = '<button class="back" id="skBack"><ha-icon icon="mdi:arrow-left"></ha-icon>Back to the stack</button><p class="intro">Tile ' + (i + 1) + ' of the stack. It takes the stack\'s size (' + (C.size || '1x1').replace('x', ' × ') + ').</p>';
        sr.getElementById('skBack').addEventListener('click', () => { this._skN = null; box.innerHTML = ''; this._skEd(true); });
        const e = document.createElement('s-tile-card-editor');
        e.addEventListener('config-changed', (ev) => { ev.stopPropagation(); const c = Object.assign({}, ev.detail.config); delete c.type; delete c.size; const cards = (Array.isArray(this._config.cards) ? this._config.cards : []).slice(); cards[i] = c; save(cards); });
        box.appendChild(e); this._skE = e;
