    if (!this.bar) { this.bar = document.createElement('s-tile-dock-bar'); }
    if (!this.bar.isConnected) (root.shadowRoot || root).appendChild(this.bar);
    const use = this.fromCard && lov.editMode ? this.fromCard : cfg;
    if (use !== this.cfg) { this.cfg = use; this.bar.config = use; }
