    const r = this.root.getBoundingClientRect();
    if (r.width) { this.bar.style.setProperty('--dk-sl', (r.left + 10) + 'px'); this.bar.style.setProperty('--dk-sr', (window.innerWidth - r.right + 10) + 'px'); this.bar.style.setProperty('--dk-st', (Math.max(r.top, 0) + 10) + 'px'); this.bar.style.setProperty('--dk-x', (r.left + r.width / 2) + 'px'); this.bar.style.setProperty('--dk-l', (r.left + 14) + 'px'); this.bar.style.setProperty('--dk-r', (window.innerWidth - r.right + 14) + 'px'); }
