    const views = conf && Array.isArray(conf.views) ? conf.views.slice(0, 5).map((v, i) => ({ name: v.title || 'View ' + (i + 1), path: '/' + base + '/' + (v.path || i), icon: v.icon || (i === 0 ? 'mdi:home' : 'mdi:view-dashboard-outline') })) : [{ name: 'Home', path: '/' + base + '/0', icon: 'mdi:home' }];
