    this.attachShadow({ mode: 'open' });
    this.shadowRoot.innerHTML = '<style>' + DW_PAL_CSS + `
:host{display:block}
h3{font-size:15px;font-weight:600;margin:20px 0 8px}
h3:first-child{margin-top:4px}
.intro{font-size:13px;color:var(--secondary-text-color);margin:0 0 10px;line-height:1.45}
.cp{border:1px solid var(--divider-color);border-radius:12px;margin-bottom:8px;overflow:hidden}
.cph{display:flex;align-items:center;gap:10px;padding:10px 12px;cursor:pointer}
.sw{width:26px;height:26px;border-radius:50%;flex:none;border:1px solid rgba(0,0,0,.12);box-sizing:border-box}
.sw.def{background:repeating-linear-gradient(45deg,#ddd 0 4px,#f5f5f5 4px 8px)}
.cpl{flex:1;min-width:0}.cpl b{display:block;font-size:13px;font-weight:600}.cpl span{font-size:12px;color:var(--secondary-text-color)}
.cpr{border:0;background:none;font:inherit;font-size:12px;color:var(--primary-color);cursor:pointer;padding:4px 6px}
.cpb{display:none;padding:4px 12px 12px}.cp.open .cpb{display:block}
.pal{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
.pal button{width:30px;height:30px;border-radius:50%;border:1px solid rgba(0,0,0,.12);cursor:pointer;padding:0}
.pal button.sel{box-shadow:0 0 0 2px var(--card-background-color),0 0 0 4px var(--primary-text-color)}
.modes{display:flex;gap:6px;margin-bottom:10px}
.modes button,.addb{border:1px solid var(--divider-color);background:none;border-radius:999px;padding:6px 12px;font:inherit;font-size:12.5px;cursor:pointer;color:var(--primary-text-color)}
.modes button.sel{background:var(--primary-color);color:var(--text-primary-color,#fff);border-color:var(--primary-color)}
.cust{display:flex;gap:8px;align-items:center}.cust input[type=color]{width:40px;height:32px;border:0;padding:0;background:none}
.cust input[type=text]{flex:1;font:inherit;font-size:13px;padding:7px 10px;border:1px solid var(--divider-color);border-radius:8px;background:var(--card-background-color);color:var(--primary-text-color)}
.vw{border:1px solid var(--divider-color);border-radius:14px;margin-bottom:10px;overflow:hidden}
.vh{display:flex;align-items:center;gap:10px;padding:8px 10px;cursor:pointer}
.vh .ic{width:38px;height:38px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;--mdc-icon-size:20px}
.vh .grow{flex:1;min-width:0}.vh b{display:block;font-size:13.5px}.vh span{display:block;font-size:12px;color:var(--secondary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vh button{border:0;background:none;cursor:pointer;color:var(--secondary-text-color);width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;--mdc-icon-size:18px;padding:0}
.vh button:hover{background:color-mix(in srgb,var(--primary-text-color) 8%,transparent)}
.vb{display:none;padding:2px 12px 12px;border-top:1px solid var(--divider-color)}.vw.open .vb{display:block}
.vb ha-form{display:block;margin:10px 0}
.adds{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
.addb{font-weight:600}
</style><h3>Player</h3><p class="intro">While music plays, the dock shows a spinning disc at its end. Tap it and the dock becomes the player; it folds back after a few seconds, or when you scroll.</p><div id="fPlayer"></div>
<h3>Look</h3><div id="fLook"></div>
<h3>Colours</h3><div id="cols"></div>
<h3>Views</h3><p class="intro">The dock's buttons, in order. The one you are on widens to show its name in its colour. A path can be a view on this dashboard (lights), a full path (/lovelace/lights) or a web address.</p><div id="views"></div>
<div class="adds"><button class="addb" id="add">+ Add a view</button><button class="addb" id="addAll">Add this dashboard's views</button></div>`;
    const mk = (id, fn) => { const f = document.createElement('ha-form'); f.hass = this._hass; f.computeLabel = (s) => DOCK_LABEL[s.name] || s.name; f.computeHelper = (s) => DOCK_HELP[s.name]; f.addEventListener('value-changed', (ev) => fn(ev.detail.value)); this.shadowRoot.getElementById(id).appendChild(f); return f; };
