    this.shadowRoot.getElementById('add').addEventListener('click', () => { const vs = this._views(); vs.push({ name: 'View ' + (vs.length + 1), path: '', icon: 'mdi:view-dashboard-outline' }); this._openV = vs.length - 1; this._setViews(vs); });
